import{_ as a,a0 as d,w as p,s,ao as i,I as r,x as t,a1 as n,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"如何在Linux上構建 RAID 10陣列 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Linux上構建 RAID 10陣列 | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Linux上構建 RAID 10陣列 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Linux上構建 RAID 10陣列 | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141009 How to set up RAID 10 for high performance and fault tolerant disk I or O on Linux","title":"如何在Linux上構建 RAID 10陣列","tag":"201412","desc":""},"relativePath":"201412/20141009 How to set up RAID 10 for high performance and fault tolerant disk I or O on Linux.md","filePath":"[post].md"}'),u={name:"201412/20141009 How to set up RAID 10 for high performance and fault tolerant disk I or O on Linux.md"},f={start:"4"};function m(I,o,D,A,g,R){const e=d("Link");return p(),s("div",null,[o[33]||(o[33]=i('<h1 id="如何在linux上構建-raid-10陣列" tabindex="-1">如何在Linux上構建 RAID 10陣列 <a class="header-anchor" href="#如何在linux上構建-raid-10陣列" aria-label="Permalink to “如何在Linux上構建 RAID 10陣列”">​</a></h1><p>RAID 10陣列（又名RAID 1+0 或先鏡像後分區）通過結合RAID 0 （讀寫操作在多個磁盤上同時並行執行）和RAID 1（數據被完全相同地寫入到兩個或更多的磁盤）兩者的特點實現高性能和高容錯性的磁盤I/O。</p><p>這篇文章會指導你如何使用五塊相同的8GB磁盤來組成一個軟件RAID 10陣列。因為組成一個RAID 10陣列至少需要4塊磁盤（比如，兩個鏡像各有一對分區組合），而且需要添加一塊額外的備用磁盤以防某塊主要的磁盤出錯。本文也會分享一些工具，在稍後用來分析RAID陣列的性能。</p><p>注意RAID 10的優缺點和其它分區方法（在不同大小的磁盤和文件系統上）的內容不在本文討論範圍內。</p><h3 id="raid-10-陣列如何工作" tabindex="-1">Raid 10 陣列如何工作？ <a class="header-anchor" href="#raid-10-陣列如何工作" aria-label="Permalink to “Raid 10 陣列如何工作？”">​</a></h3><p>如果你需要實現一種支持I/O密集操作（比如資料庫、電子郵件或web服務器）的存儲解決方案，RAID 10就是你需要的。來看看為什麼這麼説，請看下圖。</p><p><img src="https://farm4.staticflickr.com/3844/15179003008_e48806b3ef_o.png" alt=""></p><p>上圖中的文件由A、B、C、D、E和F六種塊組成，每一個RAID 1鏡像對（如鏡像1和2）在兩個磁盤上覆制相同的塊。在這樣的配置下，寫操作性能會因為每個塊需要寫入兩次而下降，每個磁盤各一次；而讀操作與從單塊磁盤中讀取相比並未發生改變。不過這種配置的好處是除非一個鏡像中有超過一塊的磁盤故障，否則都能保持冗餘以維持正常的磁盤I/O操作。</p><p>RAID 0的分區通過將數據劃分到不同的塊，然後執行同時將塊A寫入鏡像1、將塊B寫入鏡像2（以此類推）的並行操作以提高整體的讀寫性能。在另一方面，沒有任何一個鏡像包含構成主存的數據片的全部信息。這就意味着如果其中一個鏡像故障，那麼整個RAID 0組件將無法正常工作，數據將遭受不可恢復的損失。</p><h3 id="建立raid-10陣列" tabindex="-1">建立RAID 10陣列 <a class="header-anchor" href="#建立raid-10陣列" aria-label="Permalink to “建立RAID 10陣列”">​</a></h3><p>有兩種建立RAID 10陣列的可行方案：複雜法（一步完成）和嵌套法（先創建兩個或更多的RAID 1陣列，然後使用它們組成RAID 0）。本文會講述複雜法創建RAID 10陣列的過程，因為這種方法能夠使用偶數或奇數個磁盤去創建陣列，而且能以單個RAID設備的形式被管理，而嵌套法則恰恰相反（只允許偶數個磁盤，必須以嵌套設備的形式被管理，即分開管理RAID 1和RAID 0）。</p>',11)),r("p",null,[o[1]||(o[1]=t("假設你的機器已經安裝mdadm，並運行着相應的守護進程，細節參見",-1)),n(e,{href:"http://xmodulo.com/create-software-raid1-array-mdadm-linux.html"},{default:l(()=>[...o[0]||(o[0]=[t("這篇文章",-1)])]),_:1}),o[2]||(o[2]=t("。也假設每個磁盤上已經劃分出一個主分區sd[bcdef]1 （LCTT 譯註：共計五塊磁盤，這裏是從sdb - sdf）。使用命令：",-1))]),o[34]||(o[34]=i(`<pre><code>ls -l /dev | grep sd[bcdef]
</code></pre><p>查看到的輸出應該如下所示：</p><p><img src="https://farm3.staticflickr.com/2944/15365276992_db79cac82a.jpg" alt=""></p><p>然後使用下面的命令創建一個RAID 10陣列（LCTT 譯註：使用了四塊磁盤 bcde 創建）：</p><pre><code> # mdadm --create --verbose /dev/md0 --level=10 --raid-devices=4 /dev/sd[bcde]1 --spare-devices=1 /dev/sdf1 
</code></pre><p><img src="https://farm3.staticflickr.com/2946/15365277042_28a100baa2_z.jpg" alt=""></p><p>當陣列創建完畢後（最多花費幾分鐘），執行命令</p><pre><code># mdadm --detail /dev/md0
</code></pre><p>的輸出應如下所示：</p><p><img src="https://farm3.staticflickr.com/2946/15362417891_7984c6a05f_o.png" alt=""></p><p>在更進一步之前需要注意以下事項。</p><ol><li><p><strong>Used Dev Space</strong>表示陣列所使用的每一塊磁盤的容量。</p></li><li><p><strong>Array Size</strong>表示陣列的整體大小。RAID 10陣列的大小通過(N*C)/M計算，其中N是活躍磁盤的數目，C是每個活躍磁盤的容量，M是每一個鏡像中磁盤的數目。在本文的情形下，這個值等於（4*8GiB）/2 = 16GiB。</p></li><li><p><strong>Layout</strong>是整個數據佈局的詳細信息。可能的佈局數值如下所示。</p></li></ol><hr><ul><li><strong>n</strong>(默認選項)：代表就近（near）拷貝。一個數據塊的多個拷貝在不同磁盤裏有相同的偏移量。這種佈局提供和RAID 0陣列相似的讀寫性能。</li></ul><p><img src="https://farm3.staticflickr.com/2941/15365413092_0aa41505c2_o.png" alt=""></p><ul><li><strong>o</strong>代表偏移量（offset）拷貝。塊並不是在條帶裏面複製的，而是整個條帶一起復制，但是循環會打亂，所以同一個分區中複製的塊會出現在不同的磁盤。因此，一個塊的後續拷貝會出現在下一個磁盤中，一個塊接着一個塊。為了在RAID 10陣列中使用這種佈局，在創建陣列的命令中添加--layout=o2選項。</li></ul><p><img src="https://farm3.staticflickr.com/2944/15178897580_6ef923a1cb_o.png" alt=""></p><ul><li><strong>f</strong>代表遠端（far）拷貝（多個拷貝在不同的磁盤中具有不同的偏移量）。這種佈局提供更好的讀性能但帶來更差的寫性能。因此，對於讀遠遠多於寫的系統來説是最好的選擇。為了在RAID 10陣列中使用這種佈局，在創建陣列的命令中添加--layout=f2。</li></ul><p><img src="https://farm3.staticflickr.com/2948/15179140458_4a803bb194_o.png" alt=""></p><p>跟在佈局選項<strong>n</strong>、<strong>f</strong>和<strong>o</strong>後面的數字代表所需的每一個數據塊的副本數目。默認值是2，但可以是2到陣列中磁盤數目之間的某個值。提供足夠的副本數目可以最小化單個磁盤上的I/O影響。</p>`,20)),r("ol",f,[r("li",null,[o[4]||(o[4]=r("strong",null,"Chunk Size",-1)),o[5]||(o[5]=t("，參考",-1)),n(e,{href:"https://raid.wiki.kernel.org/"},{default:l(()=>[...o[3]||(o[3]=[t("Linux RAID wiki",-1)])]),_:1}),o[6]||(o[6]=t("的説明，是寫入磁盤的最小數據單元。最佳的chunk大小取決於I/O操作的速率和相關的文件大小。對於大量的寫操作，通過設置相對較大的chunk可以得到更低的開銷，但對於主要存儲小文件的陣列來説更小的chunk性能更好。為了給RAID 10指定一個chunk大小，在創建陣列的命令中添加",-1)),o[7]||(o[7]=r("strong",null,"--chunk=desired_chunk_size",-1)),o[8]||(o[8]=t("。",-1))])]),o[35]||(o[35]=r("p",null,"不幸的是，並沒有設置一個大小就能適合全局的策略來提高性能，但可以參考下面的一些方案。",-1)),r("ul",null,[r("li",null,[o[10]||(o[10]=t("文件系統：就整體而言，",-1)),n(e,{href:"http://ask.xmodulo.com/create-mount-xfs-file-system-linux.html"},{default:l(()=>[...o[9]||(o[9]=[t("XFS",-1)])]),_:1}),o[11]||(o[11]=t("據説是最好的，當然EXT4也是不錯的選擇。",-1))]),o[12]||(o[12]=r("li",null,"最佳佈局：遠端佈局能提高讀性能，但會降低寫性能。",-1)),o[13]||(o[13]=r("li",null,"副本數目：更多的副本能最小化I/O影響，但更多的磁盤需要更大的花費。",-1)),o[14]||(o[14]=r("li",null,"硬件：在相同的環境下，SSD比傳統（機械旋轉）磁盤更能帶來出性能提升",-1))]),o[36]||(o[36]=i(`<h3 id="使用dd進行raid性能測試" tabindex="-1">使用DD進行RAID性能測試 <a class="header-anchor" href="#使用dd進行raid性能測試" aria-label="Permalink to “使用DD進行RAID性能測試”">​</a></h3><p>下面的基準測試用於檢測RAID 10陣列（/dev/md0）的性能。</p><h4 id="_1-寫操作" tabindex="-1">1. 寫操作 <a class="header-anchor" href="#_1-寫操作" aria-label="Permalink to “1. 寫操作”">​</a></h4><p>往磁盤中寫入大小為256MB的單個文件：</p><pre><code># dd if=/dev/zero of=/dev/md0 bs=256M count=1 oflag=dsync 
</code></pre><p>寫入1000次512字節：</p><pre><code># dd if=/dev/zero of=/dev/md0 bs=512 count=1000 oflag=dsync 
</code></pre><p>使用dsync標記，dd可以繞過文件系統緩存，在RAID陣列上執行同步寫。這個選項用於減少RAID性能測試中緩存的影響。</p><h4 id="_2-讀操作" tabindex="-1">2. 讀操作 <a class="header-anchor" href="#_2-讀操作" aria-label="Permalink to “2. 讀操作”">​</a></h4><p>從陣列中拷貝256KiB*15000（3.9 GB）大小內容到/dev/null:</p><pre><code> # dd if=/dev/md0 of=/dev/null bs=256K count=15000 
</code></pre><h3 id="使用iozone進行raid性能測試" tabindex="-1">使用Iozone進行RAID性能測試 <a class="header-anchor" href="#使用iozone進行raid性能測試" aria-label="Permalink to “使用Iozone進行RAID性能測試”">​</a></h3>`,12)),r("p",null,[n(e,{href:"http://www.iozone.org/"},{default:l(()=>[...o[15]||(o[15]=[t("Iozone",-1)])]),_:1}),o[16]||(o[16]=t("是一款文件系統基準測試工具，用來測試各種磁盤I/O操作，包括隨機讀寫、順序讀寫和重讀重寫。它支持將結果導出為微軟的Excel或LibreOffice的Calc文件。",-1))]),o[37]||(o[37]=r("h4",{id:"在centos-rhel-7上安裝iozone",tabindex:"-1"},[t("在CentOS/RHEL 7上安裝Iozone "),r("a",{class:"header-anchor",href:"#在centos-rhel-7上安裝iozone","aria-label":"Permalink to “在CentOS/RHEL 7上安裝Iozone”"},"​")],-1)),r("p",null,[o[18]||(o[18]=t("先保證",-1)),n(e,{href:"http://xmodulo.com/how-to-set-up-rpmforge-repoforge-repository-on-centos.html"},{default:l(()=>[...o[17]||(o[17]=[t("Repoforge",-1)])]),_:1}),o[19]||(o[19]=t("可用，然後輸入：",-1))]),o[38]||(o[38]=i(`<pre><code># yum install iozone 
</code></pre><h4 id="在debian-7上安裝iozone" tabindex="-1">在Debian 7上安裝Iozone <a class="header-anchor" href="#在debian-7上安裝iozone" aria-label="Permalink to “在Debian 7上安裝Iozone”">​</a></h4><pre><code># aptitude install iozone3 
</code></pre><p>下面的iozone命令會在RAID-10陣列中執行所有測試：</p><pre><code># iozone -Ra /dev/md0 -b /tmp/md0.xls 
</code></pre><ul><li><strong>-R</strong>：往標準輸出生成兼容Excel的報告</li><li><strong>-a</strong>：以全自動模式運行所有的測試，並測試各種記錄/文件大小。記錄大小範圍：4K-16M，文件大小範圍：64K-512M。</li><li><strong>-b /tmp/md0.xls</strong>: 把測試結果存儲到一個指定的文件中</li></ul><p>希望這篇文章對你有所幫助，如果想到任何想法或建議可能會提升RAID 10的性能，請講出來。</p><hr>`,8)),r("p",null,[o[21]||(o[21]=t("via: ",-1)),n(e,{href:"http://xmodulo.com/setup-raid10-linux.html"},{default:l(()=>[...o[20]||(o[20]=[t("http://xmodulo.com/setup-raid10-linux.html",-1)])]),_:1})]),r("p",null,[o[25]||(o[25]=t("作者：",-1)),n(e,{href:"http://xmodulo.com/author/gabriel"},{default:l(()=>[...o[22]||(o[22]=[t("Gabriel Cánepa",-1)])]),_:1}),o[26]||(o[26]=t(" 譯者：",-1)),n(e,{href:"https://github.com/KayGuoWhu"},{default:l(()=>[...o[23]||(o[23]=[t("KayGuoWhu",-1)])]),_:1}),o[27]||(o[27]=t(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:l(()=>[...o[24]||(o[24]=[t("wxy",-1)])]),_:1})]),r("p",null,[o[30]||(o[30]=t("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...o[28]||(o[28]=[t("LCTT",-1)])]),_:1}),o[31]||(o[31]=t(" 原創翻譯，",-1)),n(e,{href:"http://linux.cn/"},{default:l(()=>[...o[29]||(o[29]=[t("Linux中國",-1)])]),_:1}),o[32]||(o[32]=t(" 榮譽推出",-1))])])}const k=a(u,[["render",m]]);export{T as __pageData,k as default};
